import sys; sys.path.insert(0, sys.argv[1]); from batch_lib import write_batch
M=lambda x: 'place_marre_'+x
P=[
('biscuit_ovens','The Biscuit Ovens','site',27,25,['selino'],"A street of ovens that bake nothing but ship’s biscuit, twice, until it rings like a tile. Every galley bound east carries a season of it.",
 [('ovens','The Ovens','Forty mouths of fire in a row.'),('racks','The Cooling Racks','Biscuit stacked like roof-slates.')],['selino'],
 ('pasqua','Pasqua Forn','Baker of the Ovens','a floury woman knocking two biscuits together and listening',"“Hear that?” she says. “That will last to the spice-coasts. Pasqua Forn. Do not try to eat one dry.”","Pasqua says a galley rows on her biscuit and complains about it the whole way.","“Twice baked,” Pasqua says. “Once for the weevils, once for the sea.”",'ovens','racks'),
 ('stack_biscuit','Stack biscuit','Off the peel, on to the rack, and count by the hundred.','racks',5,14,2,'skill_cookery',None)),
('water_stairs','The Water Stairs','site',33,25,['selino'],"Steps down to the great cisterns where the galleys fill their casks. Sweet water is the one thing Selino sells dearer than rope.",
 [('cisterns','The Cisterns','Dark vaults with a cold breath.'),('caskway','The Cask Way','A ramp worn smooth by rolling.')],['selino','biscuit_ovens'],
 ('tofolo','Tofolo Secc','Water-Seller of the Stairs','a man with a dipper on a chain, tasting before he sells',"He sips, nods, and holds out the dipper. “Tofolo Secc. Taste it now. In a month at sea you will dream of it.”","Tofolo can tell which cistern a cup came from, and which captain watered his crew from the cheap one.","“Gold buys spice,” Tofolo says. “Water buys coming home.”",'cisterns','caskway'),
 ('roll_casks','Roll casks to the mole','Tip it, turn it, and keep your toes out of the way.','caskway',6,17,2,'skill_athletics',None)),
('marines_yard',"The Marines' Yard",'site',28,31,['selino'],"A walled yard where the galley marines shoot at straw men from a rocking platform, because a deck does not stand still.",
 [('butts','The Butts','Straw men in a row, much mended.'),('platform','The Rocking Stage','A deck on a pivot, heaved about by four boys.')],['selino'],
 ('jacomo','Jacomo Bolz','Drill-Master of the Yard','a scarred man winding a crossbow without looking at it',"“Feet apart,” he says. “Wider. Jacomo Bolz. The sea will not hold still for you, so learn not to need it.”","Jacomo has made the run east nine times and counts that as nine times lucky.","“Anyone can hit a man on land,” Jacomo says.",'butts','platform'),
 ('shoot_butts','Shoot at the butts','Wind, lay the bolt, and loose on the roll.','butts',7,16,2,'skill_marksmanship',12)),
('pawn_arch',"The Pawnbrokers' Arch",'site',32,31,['selino'],"An archway of pawnshops between the Loop and the mole. Sailors leave their coats here in spring and buy them back in autumn, if they come back.",
 [('counters','The Counters','Grilles, scales and tickets on nails.'),('lofts','The Pledge Lofts','A season of other men’s belongings.')],['selino','marines_yard'],
 ('sabina','Sabina Pegn','Pawnbroker of the Arch','a woman weighing a ring and the man who brought it, both at a glance',"“Two months,” she says, to the ring. Then to you: “Sabina Pegn. I do not buy. I keep.”","Sabina has coats in the loft whose owners sailed ten autumns ago, and will not sell them.","“They all mean to come back for it,” Sabina says.",'counters','lofts'),
 ('tag_pledges','Tag the pledges','A ticket for each, a line in the book, and up the ladder.','lofts',8,18,2,'skill_trade',None)),
('widows_lookout',"Widows' Lookout",'site',34,22,['selino'],"A bare headland east of the town where families wait for the autumn fleet. Someone is always there from the first cold wind.",
 [('headland','The Headland','Turf, wind and a long view east.'),('cairn','The Name Cairn','A heap of stones, one for each ship that did not come.')],['water_stairs'],
 ('bettina','Bettina Spiz','Watcher of the Lookout','a woman in a shawl, knitting without looking down from the horizon',"“Sit,” she says. “It is a long watch. Bettina Spiz. I count sails in and I count sails out.”","Bettina has been right about every overdue galley for twenty years, and wishes she were not.","“Low in the water is good news,” Bettina says. “It means they found something to carry.”",'headland','cairn'),
 ('watch_sails','Watch for the fleet','Eyes east, and call the number of sails.','headland',6,19,2,'skill_seamanship',None)),
('breaming_hard','The Breaming Hard','site',24,22,['selino'],"A shelving beach where galleys are hauled over on their sides and scraped clean before the run east.",
 [('hard','The Hard','A hull on its side like a stranded whale.'),('fires','The Breaming Fires','Reed torches run along the planks to burn off the weed.')],['biscuit_ovens'],
 ('zorzi','Zorzi Rasp','Scraper of the Hard','a man with a long iron scraper and a face full of flakes',"“Mind the tallow,” he says. “Zorzi Rasp. A clean hull is a week sooner home.”","Zorzi can tell which sea a galley has been in by what is growing on her.","“Nobody thanks the man underneath,” Zorzi says.",'hard','fires'),
 ('scrape_hull','Scrape a hull','Weed, shell and old tallow, down to the wood.','hard',6,16,3,'skill_woodwork',None)),
('campo_remi','Campo dei Remi','site',50,58,['marre_city'],"A square of oar-makers. Every doorway has a rack of pale ash blades, and the paving is ankle-deep in shavings.",
 [('benches','The Shaving Benches','Long benches and longer oars.'),('racks','The Oar Racks','Blades leaning in the sun to season.')],['marre_city',M('squero_storto')],
 ('nadalin','Nadalin Forcol','Oar-Maker of the Campo','a man balancing an oar on one finger',"It tips, and he shaves a curl off. “Nadalin Forcol. Too heavy by that much. Now it is right.”","Nadalin makes the oars for the Doge’s barge and for half the smugglers in the lagoon, and will not say which pay sooner.","“A boat is a box,” Nadalin says. “The oar is the craft.”",'benches','racks'),
 ('shave_oars','Shave an oar blank','Long strokes with the grain, and stop before you think you should.','benches',7,17,2,'skill_woodwork',None)),
('calle_cambi','Calle dei Cambi','site',57,46,['marre_city'],"The money-changers’ lane by the Exchange, where every coin in the known world is weighed and found a little light.",
 [('tables','The Changing Tables','Green cloth, small scales and quick fingers.'),('strongroom','The Barred Room','A door with three locks and three keyholders.')],['marre_city',M('pescaria')],
 ('fantin','Fantin Dobl','Money-Changer of the Calle','a man ringing coins on a stone, one after another',"He rings one twice and sets it aside. “Fantin Dobl. That one is Thoolman, and clipped. Everybody clips.”","Fantin can tell a mint by the ring and a forger by the hesitation.","“I do not make money,” Fantin says. “I only stand where it turns round.”",'tables','strongroom'),
 ('weigh_coin','Weigh foreign coin','On the scale, in the book, and a mark for every light one.','tables',8,17,2,'skill_numbers',12)),
('fondaco_spezie','Fondaco delle Spezie','site',61,45,['marre_city'],"The spice warehouse behind the Exchange. The whole street sneezes when the autumn galleys unload.",
 [('floor','The Sorting Floor','Sacks slit open, sieves and scales.'),('vaults','The Sealed Vaults','Pepper under the Republic’s own seal.')],['calle_cambi',M('ponte_maschere')],
 ('samaritana','Samaritana Pevr','Garbler of Spice','a woman sifting pepper with a cloth over her nose',"She pulls the cloth down. “Samaritana Pevr. I take the dust and the stones out. You would be surprised at the stones.”","Samaritana says every sack is a tenth heavier leaving Thoolma than arriving here, and nobody is to blame.","“It is worth its weight,” Samaritana says. “So people add weight.”",'floor','vaults'),
 ('sift_pepper','Sift pepper','Shake, pick, and weigh what is left.','floor',8,17,2,'skill_trade',None)),
('teatro_remo','Teatro del Remo','site',65,54,['marre_city'],"A puppet theatre on a moored barge. The audience sits on the quay steps, and the stage rocks when a boat goes by.",
 [('stage','The Barge Stage','A painted booth with a canal behind it.'),('hold','The Puppet Hold','A hundred small people hanging by their strings.')],['marre_canal',M('corte_tinta')],
 ('ortensia','Ortensia Burat','Puppet-Mistress of the Barge','a woman with a puppet on each hand, arguing with both',"The left puppet bows. “Ortensia Burat,” says the right one. “She does the voices.”","Ortensia’s puppets say what nobody in Marre may say with a face on.","“A puppet cannot be sent to the Leads,” Ortensia says. “I have asked.”",'stage','hold'),
 ('work_strings','Work the strings','Two hands, four strings, and never look at your own fingers.','stage',16,22,2,'skill_stagecraft',12)),
('corte_barcaroli','Corte dei Barcaroli','site',52,49,['marre_city'],"The gondoliers’ court, where the stands are shared out and quarrels over fares are settled by men who all know each other’s fathers.",
 [('court','The Court','A well, a bench and a slate of stands.'),('moorings','The Night Moorings','Black boats nosed in like sleeping fish.')],['marre_city',M('osteria_bauta')],
 ('marcuola','Marcuola Stali','Steward of the Barcaroli','a broad woman chalking names on a slate and rubbing one out',"“He overcharged a senator,” she says, of the name. “Marcuola Stali. A senator! There are foreigners for that.”","Marcuola knows who was rowed where last night, and has been offered money to say.","“A gondolier sees everything and has seen nothing,” Marcuola says.",'court','moorings'),
 ('bail_boats','Bail the boats','A scoop, a sponge and forty hulls before the first fare.','moorings',5,9,1,'skill_seamanship',None)),
('caulkers_bell',"The Caulkers' Bell",'site',60,58,['marre_city'],"A tavern at the Arsenal gate that opens when the work-bell rings and fills in a hundred breaths.",
 [('room','The Long Room','Trestles, pitch-stained sleeves and noise.'),('gate','The Gate Bench','Where wives wait on pay-day.')],['marre_city',M('corte_tinta')],
 ('pierina','Pierina Stopp','Hostess of the Bell','a woman pouring a row of cups before the door has opened',"The bell rings. “Stand clear,” she says. Afterwards: “Pierina Stopp. A galley a day, and a barrel an hour.”","Pierina says the Arsenal’s secrets are safe because its men only talk about each other.","“They build the fleet,” Pierina says. “I launch the builders.”",'room','gate'),
 ('pour_cups','Pour for the shift','A row of cups, filled before the bell stops.','room',17,22,2,'skill_revelry',None)),
('long_ropewalk','The Long Ropewalk','site',64,58,['marre_city'],"A shed as long as a galley’s cable, where rope is laid by men walking backwards all day.",
 [('walk','The Walk','A quarter-mile of roof and hemp.'),('wheel','The Laying Wheel','A great wheel turned by a boy.')],['caulkers_bell','teatro_remo'],
 ('simon','Simon Canev','Rope-Maker of the Walk','a man walking backwards with hemp round his waist',"He does not turn. “Simon Canev. I have walked to Thoolma and back in this shed, and never seen where I was going.”","Simon tests every cable by hanging from it, and says that is the only honest way.","“A ship is hung on my work,” Simon says.",'walk','wheel'),
 ('walk_rope','Walk the rope','Backwards, feeding hemp, at the pace of the wheel.','walk',6,16,2,'skill_athletics',None)),
('isola_orti','Isola degli Orti','site',50,64,['marre_city'],"A flat island of kitchen gardens south of the city. Its boats go in before dawn, loaded to the gunwale with greens.",
 [('beds','The Beds','Artichokes, onions and beans in ruler-straight rows.'),('landing','The Green Landing','Flat boats, baskets and a scale.')],['campo_remi',M('stilt_huts')],
 ('gnese','Gnese Verz','Gardener of the Orti','a woman cutting artichokes into a basket on her hip',"“Take one,” she says. “Gnese Verz. The city thinks food comes from the Rialto.”","Gnese says salt wind makes the sweetest artichokes and the sourest gardeners.","“A hundred islands of stone,” Gnese says, “and one of dirt. Guess which they would miss.”",'beds','landing'),
 ('cut_greens','Cut greens for the boats','Knife low, basket full, and down to the landing.','beds',5,10,2,'skill_husbandry',None)),
('matrons_foundlings',"The Matron's Foundlings",'site',48,53,['marre_city','c_dolma'],"The foundling house of the Serene Matron. There is a wheel in the wall where a child can be left without a face being seen.",
 [('wheel','The Wheel','A turning cradle set in the street wall.'),('choir','The Choir Loft','Where the girls sing behind a grille.')],['corte_barcaroli',M('riva_ombra')],
 ('lucrezia','Madre Lucrezia Pist','Mother of the Foundlings','a brisk woman with a baby on one arm and a ledger under the other',"“This one came at midnight,” she says. “Madre Lucrezia. We name them after the day. There are a great many Sundays.”","Lucrezia says half the choirs and a third of the counting-houses of Marre learned their notes and numbers here.","“The Matron keeps what the city leaves,” Lucrezia says.",'choir','wheel'),
 ('teach_notes','Teach the choir its notes','One line at a time, until forty voices make one.','choir',9,16,2,'skill_music',None)),
('traghetto_giglio','Traghetto del Giglio','site',66,44,['marre_canal'],"A ferry-stand on the Grand Canal: two oars, one long boat and everybody standing up.",
 [('stand','The Stand','A hut, a lamp and a brass lily.'),('boat','The Crossing Boat','Twelve passengers and no seats.')],['marre_canal',M('fondamenta_specchi')],
 ('mafio','Mafio Parad','Ferryman of the Giglio','a man who rows standing, facing forward, and talks the whole way',"“Stand in the middle,” he says. “Mafio Parad. Only foreigners sit.”","Mafio has crossed the same hundred yards of water for thirty years and says it is never the same twice.","“The Families have water-gates,” Mafio says. “Everyone else has me.”",'boat','stand'),
 ('row_crossing','Row the crossing','Over and back, standing, and never touch another boat.','boat',6,20,2,'skill_seamanship',None)),
('rio_servi','Rio dei Servi','site',71,50,['marre_canal'],"The narrow back-canal behind the great palazzi, where the laundry, the kitchen boats and the gossip come and go.",
 [('steps','The Washing Steps','Sheets on lines across the water.'),('doors','The Kitchen Doors','Low doors at the waterline, each with its house colour.')],['marre_canal'],
 ('giacomina','Giacomina Scov','Laundress of the Rio','a woman wringing a sheet with a great house’s crest on it',"“Look,” she says, holding up a wine stain. “Somebody had a good night. Giacomina Scov. I know all of them by their linen.”","Giacomina says a house’s troubles show in the wash a month before they show at the front door.","“Up there they wear masks,” Giacomina says. “Down here I wash what is under them.”",'steps','doors'),
 ('wring_sheets','Wring the sheets','Two to a sheet, twist against each other, and hang it square.','steps',6,15,2,'skill_clothwork',None)),
("ca_zorzan","Ca' Zorzan",'site',73,45,['marre_canal'],"The new house of a spice family that is not one of the Ten and would like its grandchildren to be. Everything in it is a little too gilded.",
 [('hall','The Water-Hall','Marble that still smells of the mason.'),('counting','The Counting-Room','Where the house’s real business is done.')],['marre_canal','rio_servi'],
 ('agostin','Agostin Mezan','Steward of the house','a careful man straightening a picture that was already straight',"“Do not lean on that,” he says. “It is new. Everything is. Agostin Mezan. I serve the house.”","Agostin has served an old house and a new one, and says the new one counts the spoons.","“Money takes a year,” Agostin says. “A name takes a hundred.”",'hall','counting'),
 ('polish_hall','Polish the water-hall','Wax, cloth, and every tile until it shows the ceiling.','hall',6,12,2,'skill_stewardship',None)),
('sand_barges','The Sand Barges','site',76,28,['marre_isles'],"The landing on the Isles where white sand and soda-ash come in. It is the only part of the Isles a stranger may walk on unwatched.",
 [('landing','The Landing','Barges of sand like low white hills.'),('sheds','The Ash Sheds','Sacks of soda-ash kept dry under tile.')],['marre_isles',M('guard_boats')],
 ('rocco','Rocco Sabion','Bargeman of the Sand','a man shovelling white sand in an easy, endless swing',"“Glass is sand, ash and a secret,” he says. “Rocco Sabion. I bring the sand. Nobody tells me the secret.”","Rocco has landed sand here for twenty years and never been past the second shed.","“I can leave,” Rocco says. “That is the difference between us.”",'landing','sheds'),
 ('shovel_sand','Shovel sand ashore','Swing, throw, swing. The barge rises as you empty it.','landing',6,16,2,'skill_athletics',None)),
('bead_row',"Bead-Stringers' Row",'site',80,30,['marre_isles'],"A lane of women stringing glass beads by the thousand, on wires fanned out like a hand. The galleys carry them east by the barrel.",
 [('doorways','The Doorways','A tray of beads on every knee.'),('lampshop','The Lamp-Workers’ Shop','Rods of glass turned to beads over a flame.')],['marre_isles','sand_barges'],
 ('maddalena','Maddalena Perl','Bead-Stringer of the Row','a woman dipping a fan of wires into a tray of beads',"She lifts the wires, full. “Maddalena Perl. Forty strings before noon. Talk if you like. I do not need my eyes for it.”","Maddalena says the beads are worth more across the sea than the pepper that comes back.","“The masters make mirrors for doges,” Maddalena says. “We make money.”",'doorways','lampshop'),
 ('string_beads','String beads','Dip the wires, shake, and slide them down the thread.','doorways',7,18,2,'skill_kilncraft',None)),
('old_masters_isle',"The Old Masters' Isle",'site',84,28,['marre_isles'],"A small island where glassmakers too old for the furnace live out their days, well fed, well housed and still not allowed to leave.",
 [('loggia','The Loggia','Chairs in the sun, facing the furnaces.'),('garden','The Glass Garden','Flowers of coloured glass, made for no one.')],['bead_row',M('ash_isle')],
 ('domenego','Domenego Sofi','Master of the Isle, retired','an old man with burn-scarred forearms, blowing a soap bubble through a straw',"The bubble floats off. “My lungs still know how,” he says. “Domenego Sofi. Forty years at the furnace. Now I do that.”","Domenego can describe a mirror he made in his youth, and says it hangs in a palace he will never see.","“They buried the secret in us,” Domenego says. “So they must keep the graves close.”",'loggia','garden'),
 ('read_to_masters','Read to the old masters','The news from the city, slowly, and twice for the deaf ones.','loggia',9,17,1,'skill_letters',None)),
('goat_rock','Goat Rock','wild',96,40,['morena'],"A steep islet off Morena with a signal mast and a few goats. Flags from here reach the castle before a ship does.",
 [('mast','The Signal Mast','A mast, a locker of flags and a great deal of wind.'),('hut','The Signalman’s Hut','Stone, low and roped down.')],['morena'],
 ('polo','Polo Segn','Signalman of Goat Rock','a man hauling a flag up hand over hand, squinting east',"“Two sail, friendly, slow,” he says, and makes fast. “Polo Segn. I tell the castle what is coming. They decide if it is welcome.”","Polo has not been off the rock since spring, and says the goats have better manners than the garrison.","“Both empires sail past me,” Polo says. “Neither waves.”",'mast','hut'),
 ('hoist_flags','Hoist the signals','Bend on, haul up, and hold until the castle answers.','mast',6,19,1,'skill_seamanship',None)),
('salvage_camp','The Salvage Camp','site',86,72,['xonia_shore'],"A camp of tents on the white beach, where a crew raises marble from the shallows at low tide and ships it to the city’s masons.",
 [('sledges','The Sledges','Timber sledges and a team of oxen, knee-deep.'),('tents','The Tents','Canvas, cook-smoke and salt-stiff rope.')],['xonia_shore'],
 ('olivo','Olivo Tuff','Foreman of the Salvage','a sunburnt man reading the tide off a notched pole',"“An hour,” he says. “Then it is over our heads again. Olivo Tuff. We work when the sea lets us.”","Olivo says half the new palazzi stand on steps somebody else carved, long ago.","“We do not ask who built it,” Olivo says. “We ask what it weighs.”",'sledges','tents'),
 ('haul_marble','Haul a block ashore','Rope, rollers and the ox-team, before the tide turns.','sledges',6,18,2,'skill_athletics',None)),
('divers_raft',"The Divers' Raft",'wild',88,22,['xonia_sunken'],"A raft anchored over the drowned streets, where sponge-divers go down on a stone and come up with whatever they can carry.",
 [('raft','The Raft','Planks, a brazier and a rack of flat stones.'),('line','The Stone Line','A rope straight down into the blue.')],['xonia_sunken',M('ash_isle')],
 ('fosca','Fosca Spong','Diver of the Raft','a woman breathing slowly with her eyes shut, a stone in her lap',"She opens her eyes. “Do not talk to a diver before she goes down. Fosca Spong. After, I will talk all you like.”","Fosca has walked on the drowned square and says the statues watch you leave.","“Forty feet is not far,” Fosca says. “Except straight down.”",'raft','line'),
 ('tend_line','Tend a diver’s line','Pay out, feel for the tug, and haul like your own life.','line',7,16,2,'skill_seamanship',12)),
('keepers_cove',"Keeper's Cove",'site',20,76,['wp_lighthouse'],"The one safe landing below Cape Drown, where the oil for the great lamp is brought ashore and carried up the cliff by hand.",
 [('landing','The Landing','A shelf of rock and an iron ring.'),('path','The Oil Path','Four hundred steps, with a rope.')],['wp_lighthouse',M('pilots_rest')],
 ('bernardo','Bernardo Oli','Oil-Carrier of the Cove','a man with a jar on his back and a hand on the rope',"He sets the jar down with care. “Bernardo Oli. Forty jars a month. The lamp drinks more than I do.”","Bernardo says he has kept more ships off the rocks than any captain, one jar at a time.","“If I stop, the lamp stops,” Bernardo says. “So I do not stop.”",'path','landing'),
 ('carry_oil','Carry oil up the path','One jar, four hundred steps, and do not look down.','path',6,17,2,'skill_athletics',None)),
]
write_batch(sys.argv[2] if len(sys.argv) > 2 else '.', 'marre', 'marre-02', P, "Marre, second batch: twenty-five small places in Selino, the city, the Grand Canal, the Glass Isles and the outer waters.", water=True)
